        hits+=1
        print(f"CALLED: {dll}!{nm} IAT 0x{a:x}")
for key in ('SetupDi','HidD_','CoCreateInstance','VariantInit'):
    print(key, [ (dll,nm,hex(a)) for a,(dll,nm) in addrs.items() if key.lower() in nm.lower()])
print("total imported-by-call referenced:", hits)

