        if v<=o<v+s: return d[r+(o-v): r+(o-v)+n]
    return b''
def fmt(b):
    a,b2,c=struct.unpack('<IHH',b[:8]); return f"{{{a:08X}-{b2:04X}-{c:04X}-{b[8]:02X}{b[9]:02X}-{b[10:].hex().upper()}}}"
for va in (0x14003af50,0x14003b490,0x14003af68,0x1400396a0,0x14002bdd8,0x14002bdc8):
    b=rd(va)
